  var LEVELS = ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'];
  var MAX_HISTORY_POINTS = 288;   // B1/T-1129: 24ч × 5 мин
  // 10.10 (п.2, ADR-1010-2): временная сетка графика истории ключей.
