  function _wsModuleById(slug) {
    if (!slug) return null;
    for (var i = 0; i < MODULES.length; i++) {
      var m = MODULES[i];
      var s = m.routeSlug || String(m.id || '').replace(/^mod_/, '');
      if (s === slug) return m;
    }
    return null;
  }
