      memoryCatalogTypes: function () {
        return [
          { id: 'all', label: 'Всё' },
          { id: 'facts', label: 'Факты' },
          { id: 'people', label: 'Люди' },
          { id: 'relations', label: 'Связи' },
          { id: 'context', label: 'Контекст' },
          { id: 'episodes', label: 'Эпизоды' },
        ];
      },
